# Ảnh gốc có một phiến đế đá trắng ở đáy; cắt bỏ để tượng "đứng" sạch hơn.
def row_brightness(img, y):
    vals = []
    for x in range(0, img.width, 7):
        r, g, b, a = img.getpixel((x, y))
        if a > 200:
            vals.append((r + g + b) / 3.0)
    return sum(vals) / len(vals) if vals else 255.0

w, h = im.size
bottom_avg = sum(row_brightness(im, y) for y in range(max(0, h - 18), h)) / min(18, h)
if bottom_avg > 170:
    crop_y = h
    for y in range(h - 1, max(0, h - 170), -1):
        if row_brightness(im, y) < 150:
            crop_y = min(h, y + 2)
            break
    if crop_y < h:
        im = im.crop((0, 0, w, crop_y))
        alpha = im.getchannel("A")
        print(f"Đã cắt bỏ đế trắng ở đáy: còn {im.size}")

