Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead($out)
$fonts = $zip.Entries | Where-Object { $_.FullName -like 'ppt/fonts/*' }
if ($fonts) { $fonts | Select-Object FullName, Length } else { Write-Output "NO EMBEDDED FONTS" }
$entry = $zip.GetEntry('ppt/presentation.xml')
$reader = New-Object System.IO.StreamReader($entry.Open())
$xml = $reader.ReadToEnd()
$reader.Close()
if ($xml -match 'embeddedFontLst') { Write-Output "embeddedFontLst FOUND" } else { Write-Output "embeddedFontLst MISSING" }
$zip.Dispose()
